import{_ as a,c as e,o as l,a4 as i}from"./chunks/framework.CpVK_f0P.js";const b=JSON.parse('{"title":"Self Learning English","description":"","frontmatter":{},"headers":[],"relativePath":"introduce.md","filePath":"introduce.md"}'),n={name:"introduce.md"},r=i(`<h1 id="self-learning-english" tabindex="-1">Self Learning English <a class="header-anchor" href="#self-learning-english" aria-label="Permalink to &quot;Self Learning English&quot;">​</a></h1><p>这是一个以真实输出为核心的个人英语训练仓库。</p><h2 id="当前目标" tabindex="-1">当前目标 <a class="header-anchor" href="#当前目标" aria-label="Permalink to &quot;当前目标&quot;">​</a></h2><ul><li>听懂会议和日常对话</li><li>听完一段内容后，用英语复述大意</li><li>用简单完整的句子进行日常交流</li><li>完成站会汇报、Bug 描述、技术讨论和需求确认</li><li>用英语描述技术方案和问题</li><li>主动使用练过的词汇和句式，而不只是看得懂</li></ul><h2 id="核心学习流程" tabindex="-1">核心学习流程 <a class="header-anchor" href="#核心学习流程" aria-label="Permalink to &quot;核心学习流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>输入（听材料）</span></span>
<span class="line"><span>→ 第一次输出（复述）</span></span>
<span class="line"><span>→ 发现问题（语法、表达、词汇）</span></span>
<span class="line"><span>→ 提炼 3～5 个表达</span></span>
<span class="line"><span>→ 用自己的场景做替换练习</span></span>
<span class="line"><span>→ 再次输出（修正后的复述）</span></span>
<span class="line"><span>→ 把分析和目标写入练习记录</span></span></code></pre></div><h2 id="当前学习计划" tabindex="-1">当前学习计划 <a class="header-anchor" href="#当前学习计划" aria-label="Permalink to &quot;当前学习计划&quot;">​</a></h2><p>采用两档计划：忙时完成最低版，时间充足时完成完整版。最低版是每天的底线， 完整版不是必须每天完成的硬指标。</p><h3 id="当前材料" tabindex="-1">当前材料 <a class="header-anchor" href="#当前材料" aria-label="Permalink to &quot;当前材料&quot;">​</a></h3><ul><li>主线：《走遍美国》，按 Act 做精听、复述、纠错和再次复述</li><li>补充：<a href="https://learnenglish.britishcouncil.org/free-resources/listening/a2" target="_blank" rel="noreferrer">British Council A2 Listening</a> 的成人日常和工作场景</li><li>选用：<a href="https://www.bbc.co.uk/learningenglish/english/features/6-minute-english" target="_blank" rel="noreferrer">BBC 6 Minute English</a> 中真正感兴趣的成人主题</li><li>输出：站会汇报、Bug 描述、技术讨论和需求确认</li></ul><h3 id="最低版-每天-20-30-分钟" tabindex="-1">最低版：每天 20～30 分钟 <a class="header-anchor" href="#最低版-每天-20-30-分钟" aria-label="Permalink to &quot;最低版：每天 20～30 分钟&quot;">​</a></h3><ol><li>听和理解 5～8 分钟：选择 1～3 分钟的材料，先盲听，再看文本确认。</li><li>第一次脱稿复述 5 分钟：先完整说出来，不在卡点上长时间停留。</li><li>检查和提炼 5～8 分钟：只选 3～5 个最影响表达的问题或句式。</li><li>第二次复述 5 分钟：使用修正后的简单句，再完整说一遍。</li></ol><p>如果当天只能做一件事，就复述当前《走遍美国》Act，不同时开启多份材料。</p><h3 id="完整版-每天-60-90-分钟" tabindex="-1">完整版：每天 60～90 分钟 <a class="header-anchor" href="#完整版-每天-60-90-分钟" aria-label="Permalink to &quot;完整版：每天 60～90 分钟&quot;">​</a></h3><ul><li>核心输出 20～30 分钟：完成最低版</li><li>跟读 10～15 分钟：模仿当前材料的重音、停顿和连读</li><li>成人短听力 10～15 分钟：听完后用 3～5 句英语复述</li><li>工作场景 15～20 分钟：写关键词，脱稿表达，检查问题，再说一遍</li><li>词汇维护 5～10 分钟（可选）：只复习已有内容，不设每日新词数量</li></ul><h3 id="每周工作场景" tabindex="-1">每周工作场景 <a class="header-anchor" href="#每周工作场景" aria-label="Permalink to &quot;每周工作场景&quot;">​</a></h3><ul><li>周一 / 周四：Stand-up，说明昨天做了什么、今天做什么、是否有阻塞</li><li>周二 / 周五：描述真实 Bug，包括预期、实际结果、复现步骤和原因猜测</li><li>周三 / 周六：让 AI 扮演 PM 或同事，练技术讨论和需求确认</li><li>周日：复述本周最难的一段材料，整理遗留问题；状态不好时休息</li></ul><h3 id="材料安排" tabindex="-1">材料安排 <a class="header-anchor" href="#材料安排" aria-label="Permalink to &quot;材料安排&quot;">​</a></h3><ul><li>当前阶段：以《走遍美国》为主，搭配 British Council A2 Listening； BBC 6 Minute English 只作为补充</li><li>下一阶段：逐步加入英文技术视频、会议 talk 和 Business English Pod</li><li>后续阶段：真实会议、技术视频和 TED 成为主线，影视只作为补充</li></ul><p>材料必须带文本或字幕，主题要对成人生活或工作有用，连续语言要占主要部分。 儿童主题、无意义声音或音效过多的内容直接淘汰。</p><h3 id="听力级别升级标准" tabindex="-1">听力级别升级标准 <a class="header-anchor" href="#听力级别升级标准" aria-label="Permalink to &quot;听力级别升级标准&quot;">​</a></h3><p>当前听 A2 新材料，第一遍大约能理解 50%，因此 A2 继续作为主训练级别，B1 暂时只作少量试听。</p><p>听懂率按主要信息估算，不按听出的单词数量计算：能否说出主题、人物目的、 关键事实和最后结果。</p><ul><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/a2" target="_blank" rel="noreferrer">A2 Listening</a>： 当前主线</li><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/b1" target="_blank" rel="noreferrer">B1 Listening</a>： 电话、会议、采访以及清晰的日常或工作话题</li><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/b2" target="_blank" rel="noreferrer">B2 Listening</a>： 更长的广播、访谈、演讲和包含复杂观点的熟悉话题</li></ul><p>同一级别连续 5 段新材料都满足以下条件，再把下一级别加入主训练：</p><ul><li>第一遍不看文本理解约 70%，第二遍达到约 80%</li><li>配套理解题正确率达到 80%</li><li>不看文本能用 3～5 句英语复述主题、关键事件和结果</li></ul><p>第一次听懂 40%～60% 适合精听；低于 40% 只作偶尔尝试；稳定达到 70% 以上 开始加入下一级别。升级后的前两周按当前级别 70%、下一级别 30% 分配。</p><h3 id="每四周固定测试" tabindex="-1">每四周固定测试 <a class="header-anchor" href="#每四周固定测试" aria-label="Permalink to &quot;每四周固定测试&quot;">​</a></h3><ul><li>2 分钟自我介绍 + 3 分钟 stand-up + 5 分钟项目介绍</li><li>听一段没听过的 2 分钟材料两遍，然后脱稿复述</li><li>与 AI 或真人进行 10 分钟连续工作场景对话</li><li>用 10 分钟写一封进度汇报或 Bug 描述</li></ul><p>每次保持同题、同时长和同遍数。四到八周没有变化时，调整材料难度或输出量， 不单纯增加学习时长。</p><h2 id="记录原则" tabindex="-1">记录原则 <a class="header-anchor" href="#记录原则" aria-label="Permalink to &quot;记录原则&quot;">​</a></h2><ul><li>不收集完整教材，只记录训练中真实遇到的问题</li><li>一次只训练 3～5 个表达</li><li>只记录真实犯过的错误</li><li>过时内容优先归档；删除知识类内容前先确认范围</li><li>语法随用随查，保留已有语法和发音资料</li></ul><h2 id="当前训练" tabindex="-1">当前训练 <a class="header-anchor" href="#当前训练" aria-label="Permalink to &quot;当前训练&quot;">​</a></h2><p>正在使用《走遍美国》(Family Album, U.S.A.) 练习听力和复述。</p><p>最新记录：<a href="/self-learning-english/practice/family-album-usa/episode-02-act-03.html">Episode 2 Act 3 — The Blind Date</a></p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>我从 2024 年 4 月开始系统学习英语，到 2025 年初暂停，累计投入约 900 小时， 词汇量达到 7500 左右，口语和听力约 A2 水平。</p><p>2026 年 7 月恢复学习，目标是提升实际交流能力。当前以每天 20～30 分钟为最低 目标，时间充足时完成 60～90 分钟完整版，重点从大量输入转向输出驱动。</p><p>学习方法参考：<a href="https://github.com/xiaolai/everyone-can-use-english" target="_blank" rel="noreferrer">《人人都能用英语》</a> 和<a href="https://baike.baidu.com/item/%E4%BA%8C%E8%AF%AD%E4%B9%A0%E5%BE%97%E7%90%86%E8%AE%BA/7802838" target="_blank" rel="noreferrer">二语习得理论</a>。</p>`,39),t=[r];function s(h,o,c,p,u,d){return l(),e("div",null,t)}const f=a(n,[["render",s]]);export{b as __pageData,f as default};
